#!/usr/bin/env bash
# recipes/crate-malloc-buf--0-0-6/build.sh -- stage the malloc_buf 0.0.6 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/malloc_buf-0.0.6"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
